import{_ as i,o as t,c as a,a6 as e}from"./chunks/framework.B_q3ZJNF.js";const k=JSON.parse('{"title":"HTTPS 与安全头：上线 TLS 前前端要懂的常识","description":"","frontmatter":{"title":"HTTPS 与安全头：上线 TLS 前前端要懂的常识"},"headers":[],"relativePath":"nginx-course/11-https-and-security.md","filePath":"nginx-course/docs/11-https-and-security.md"}'),n={name:"nginx-course/11-https-and-security.md"};function p(l,s,o,h,r,c){return t(),a("div",null,[...s[0]||(s[0]=[e(`<h1 id="https-与安全头-上线-tls-前前端要懂的常识" tabindex="-1">HTTPS 与安全头：上线 TLS 前前端要懂的常识 <a class="header-anchor" href="#https-与安全头-上线-tls-前前端要懂的常识" aria-label="Permalink to &quot;HTTPS 与安全头：上线 TLS 前前端要懂的常识&quot;">​</a></h1><p>全站升级 HTTPS 的第二天，工单列表比发版还热闹。地址栏的锁是灰的，点开一看「此页面包含不安全的资源」：三个接口还写着 <code>http://api.example.com</code>，浏览器直接拦截——升级 HTTPS 后的页面里，任何 http 资源都成了&quot;混合内容（mixed content）&quot;。客服还没回复完，聊天室的用户又来了：WebSocket 全断了，前端还连的 <code>ws://</code>——HTTPS 页面里只允许 <code>wss://</code>。第三天，市场部发现从某些运营商网络进来的老用户（http 链接跳转过来的）页面右下角有运营商插的广告 iframe——HTTP 明文传输，中间人想插什么插什么。</p><p>这一章没有 mini-nginx 代码——TLS 握手在 Node 里也是一行 <code>https.createServer</code> 的事，难点从来不在实现，而在<strong>理解每个环节解决什么问题、前端要配合改什么</strong>。它是全书的 principle 章之二，也是上线前的 checklist。</p><h2 id="证书链-三层的信任传递" tabindex="-1">证书链：三层的信任传递 <a class="header-anchor" href="#证书链-三层的信任传递" aria-label="Permalink to &quot;证书链：三层的信任传递&quot;">​</a></h2><p>HTTPS = HTTP + TLS。TLS 解决两件事：<strong>加密</strong>（中间人看不到内容，运营商插广告的空间消失）和<strong>身份</strong>（你连的确实是 example.com，不是钓鱼站）。身份靠证书证明，而证书本身是一条三层信任链：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>根证书（Root CA）              ← 内置在操作系统/浏览器里，信任的起点</span></span>
<span class="line"><span>  └─ 签发 → 中间证书（Intermediate）  ← CA 替自己隔离风险用的层</span></span>
<span class="line"><span>        └─ 签发 → 叶子证书（你的）    ← 绑定你的域名，发给你</span></span></code></pre></div><p>浏览器验证时从叶子往上追到根，任何一环缺失或域名不匹配，连接报证书错误。前端最该记住的两个证书坑：</p><ol><li><strong>部署时必须把中间证书一起部署</strong>（fullchain 而不是只放叶子证书）。漏掉中间证书的现象很有迷惑性：<strong>你自己电脑打开正常</strong>（可能缓存过中间证书），部分用户浏览器报「证书链不完整」——又是&quot;一半用户有问题&quot;的家族事故。</li><li><strong>证书有有效期</strong>，Let&#39;s Encrypt 免费 90 天，忘了续期就是全站红色警告页。务必上自动续期（certbot timer / acme.sh cron），不要指望人肉记忆。</li></ol><h2 id="nginx-侧的最小-https-配置" tabindex="-1">Nginx 侧的最小 HTTPS 配置 <a class="header-anchor" href="#nginx-侧的最小-https-配置" aria-label="Permalink to &quot;Nginx 侧的最小 HTTPS 配置&quot;">​</a></h2><p>上线 TLS 的网关配置骨架，逐段都有存在理由：</p><div class="language-nginx vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">nginx</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">server</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  listen </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">443</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ssl;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  server_name </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">shop.example.com;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  ssl_certificate </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    /etc/nginx/certs/fullchain.pem;  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 叶子 + 中间证书，一个都不能少</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  ssl_certificate_key </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/etc/nginx/certs/privkey.pem;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  ssl_protocols </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      TLSv1.2 TLSv1.3;                 </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 老协议有已知漏洞，别开</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">server</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  listen </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">80</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  server_name </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">shop.example.com;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  return</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 301</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> https://$host$request_uri;                </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># http 全量跳 https</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><code>301</code> 那个 server 块回答了&quot;老用户的 http 链接怎么办&quot;——永久重定向到 https。但 301 有个真空期：用户<strong>第一次</strong>访问 http 时，重定向响应本身还是明文的，中间人可以篡改它（这就是运营商劫持的原理）。补上这块缺口的是 <strong>HSTS（HTTP Strict Transport Security）</strong>：</p><div class="language-nginx vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">nginx</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">add_header </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Strict-Transport-Security </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;max-age=31536000; includeSubDomains&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> always;</span></span></code></pre></div><p>它告诉浏览器：&quot;这个域名一年内只许用 https，直接在本地拒绝 http 访问&quot;。第一次之后，连那次明文重定向都省了——中间人篡改的窗口从&quot;每次访问&quot;缩到&quot;第一次访问&quot;。<code>includeSubDomains</code> 把所有子域名一起管上（注意：上它之前确认没有任何子域名还只能跑 http，否则会直接打不开）。</p><h2 id="前端配合清单-混合内容的完整拆除" tabindex="-1">前端配合清单：混合内容的完整拆除 <a class="header-anchor" href="#前端配合清单-混合内容的完整拆除" aria-label="Permalink to &quot;前端配合清单：混合内容的完整拆除&quot;">​</a></h2><p>网关配好了，前端侧的活儿一样具体：</p><ul><li><strong>接口地址全部走协议相对或 https</strong>。<code>http://api.example.com</code> 在 https 页面里被拦，<code>//api.example.com</code>（协议相对）或干脆同源 <code>/api</code>（第 5 章的代理方案）都行。检查生产配置里的 API baseURL 是不是写死了 <code>http://</code>。</li><li><strong>WebSocket 换 <code>wss://</code></strong>，且注意第 6 章的知识点依然成立：wss 穿透代理同样需要 Upgrade 头透传。</li><li><strong>图片、字体、iframe 等子资源</strong>：被动混合内容（img/audio/video）浏览器目前多会自动升级或放行，但<strong>主动混合内容</strong>（script、fetch、XHR、websocket）一律硬拦。别赌策略，统一换干净。</li><li><strong><code>crossorigin</code> 的资源</strong>换完协议后重新过一遍第 10 章的跨域授权。</li></ul><h2 id="csp-给页面装一道内容防火墙" tabindex="-1">CSP：给页面装一道内容防火墙 <a class="header-anchor" href="#csp-给页面装一道内容防火墙" aria-label="Permalink to &quot;CSP：给页面装一道内容防火墙&quot;">​</a></h2><p>最后一个安全头值得单独认识——内容安全策略（CSP）。前面所有手段是&quot;修好自己&quot;，CSP 是&quot;就算有 XSS 注入，也让他加载不了外部脚本&quot;：</p><div class="language-nginx vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">nginx</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">add_header </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Content-Security-Policy </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;default-src &#39;self&#39;; script-src &#39;self&#39;; connect-src &#39;self&#39; https://api.example.com; img-src &#39;self&#39; data: https:&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> always;</span></span></code></pre></div><p>语义按资源类型白名单化：脚本只许自家域，接口只许自家和 api 域，图片放开 https。它的调试姿势要记住：先上 <code>Content-Security-Policy-Report-Only</code>（只上报不拦截，看 console 里的违规报告），确认无误再切换到强制模式——直接上强制 CSP 打断第三方脚本，是另一种&quot;上线即事故&quot;。</p><p>顺带收个尾：<code>add_header</code> 在这里全部带了 <code>always</code> 参数——第 10 章说过 add_header 默认不对 4xx/5xx 生效，安全头恰恰要在错误页上也生效，这个参数是标准搭配。</p><h2 id="验证-这一章的-测试-是工具链" tabindex="-1">验证（这一章的&quot;测试&quot;是工具链） <a class="header-anchor" href="#验证-这一章的-测试-是工具链" aria-label="Permalink to &quot;验证（这一章的&quot;测试&quot;是工具链）&quot;">​</a></h2><ul><li><strong>SSL Labs</strong>（ssllabs.com/ssltest）：在线扫你的域名，证书链完整性、协议版本、加密套件一次给全，A 是及格线。</li><li><strong>浏览器 DevTools 的 Security 面板</strong>：一眼看混合内容还剩几个，点开能定位到具体资源。</li><li><code>curl -I http://shop.example.com</code>：确认 301 跳 https；<code>curl -I https://...</code> 确认 HSTS 头在场。</li></ul><hr><p><strong>本章要点</strong>：TLS 一次解决加密与身份，证书链三层缺一不可（部署 fullchain、自动续期）；http→https 用 301，HSTS 补上&quot;第一次访问&quot;的明文窗口；前端要拆干净混合内容——接口、wss、子资源全换；CSP 用 Report-Only 起步再转强制，安全头记得带 <code>always</code>。</p>`,26)])])}const g=i(n,[["render",p]]);export{k as __pageData,g as default};
